5→const typed = (message, code, fields = {}) => Object.assign(new Error(message), { code, ...fields });
6→
7→function boundedExec(file, args, opts) {
8→  return new Promise((resolve, reject) => {
9→    const child = spawn(file, args, { cwd: opts.cwd, shell: false, env: opts.env, stdio: ['ignore', 'pipe', 'pipe'] });
10→    let stdout = ''; let stderr = ''; let failure = null; let settled = false;
11→    const finish = (error, value) => { if (settled) return; settled = true; clearTimeout(timer); if (error) reject(error); else resolve(value); };
12→    const stop = (error) => { failure ??= error; try { child.kill('SIGKILL'); } catch { /* already gone */ } };
13→    const append = (stream, chunk) => {
14→      if (stream === 'stdout') stdout += chunk; else stderr += chunk;
15→      if (Buffer.byteLength(stdout) + Buffer.byteLength(stderr) > opts.maxOutputBytes) stop(typed('structured merge resolver output exceeded deployment budget', 'structured_tool_output_too_large'));
16→    };
17→    child.stdout.setEncoding('utf8'); child.stderr.setEncoding('utf8');
18→    child.stdout.on('data', (chunk) => append('stdout', chunk)); child.stderr.on('data', (chunk) => append('stderr', chunk));
19→    child.on('error', (error) => finish(error?.code === 'ENOENT' ? typed('structured merge resolver is unavailable', 'structured_tool_unavailable') : typed(`structured merge resolver spawn failed: ${error.message}`, 'structured_tool_failed')));
20→    child.on('close', (exitCode) => failure ? finish(failure) : finish(null, { stdout, stderr, exitCode }));
21→    const timer = setTimeout(() => stop(typed('structured merge resolver timed out', 'structured_tool_timeout')), opts.timeoutMs);
22→  });
23→}
