25→export class MergirafResolver {
26→  constructor(opts = {}) {
27→    if (typeof opts.binary !== 'string' || opts.binary.length === 0) throw new TypeError('Mergiraf binary required');
28→    if (!Number.isSafeInteger(opts.timeoutMs) || opts.timeoutMs <= 0) throw new TypeError('Mergiraf timeoutMs must be deployment-derived');
29→    if (!Number.isSafeInteger(opts.maxOutputBytes) || opts.maxOutputBytes <= 0) throw new TypeError('Mergiraf maxOutputBytes must be deployment-derived');
30→    if (!Number.isSafeInteger(opts.maxFileBytes) || opts.maxFileBytes <= 0) throw new TypeError('Mergiraf maxFileBytes must be deployment-derived');
31→    this.binary = opts.binary; this.timeoutMs = opts.timeoutMs; this.maxOutputBytes = opts.maxOutputBytes; this.maxFileBytes = opts.maxFileBytes;
32→    this.execFile = opts.execFile ?? boundedExec;
33→  }
34→
35→  identity() { return Object.freeze({ tool: 'mergiraf', binary: this.binary }); }
36→
37→  async resolve({ cwd, relativePath }) {
38→    if (typeof cwd !== 'string' || typeof relativePath !== 'string' || relativePath.length === 0) throw new TypeError('structured merge resolver requires cwd and relativePath');
39→    let observed;
40→    try {
41→      observed = await this.execFile(this.binary, ['solve', relativePath], {
42→        cwd, shell: false, timeoutMs: this.timeoutMs, maxOutputBytes: this.maxOutputBytes,
43→        env: { PATH: process.env.PATH ?? '', LANG: 'C', LC_ALL: 'C' },
44→      });
45→    } catch (error) {
46→      if (error?.code?.startsWith('structured_')) throw error;
47→      if (error?.code === 'ENOENT') throw typed('structured merge resolver is unavailable', 'structured_tool_unavailable');
48→      throw typed(`structured merge resolver failed: ${error?.message ?? error}`, 'structured_tool_failed');
49→    }
50→    const stdout = String(observed?.stdout ?? ''); const stderr = String(observed?.stderr ?? '');
51→    if (Buffer.byteLength(stdout) + Buffer.byteLength(stderr) > this.maxOutputBytes) throw typed('structured merge resolver output exceeded deployment budget', 'structured_tool_output_too_large');
52→    const evidence = { exitCode: observed?.exitCode ?? null, stdoutDigest: digest(stdout), stderrDigest: digest(stderr) };
53→    if (/fall(?:ing)?\s+back|line[- ]based\s+merge/i.test(`${stdout}\n${stderr}`)) return Object.freeze({ status: 'parse_fallback', ...evidence });
54→    if (observed?.exitCode !== 0) return Object.freeze({ status: 'unresolved', ...evidence });
55→    if (!/solved\s+\d+\s+conflict/i.test(stdout)) return Object.freeze({ status: 'unknown', ...evidence });
56→    return Object.freeze({ status: 'resolved', ...evidence });
57→  }
58→}
