1→import test from 'node:test';
2→import assert from 'node:assert/strict';
3→import { execFileSync } from 'node:child_process';
4→import { chmodSync, existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
5→import { join } from 'node:path';
6→import { tmpdir } from 'node:os';
7→import { createBrief, createDriver, MockAdapter, MergirafResolver } from '../src/index.mjs';
8→
9→const git = (args, cwd) => execFileSync('git', args, { cwd, encoding: 'utf8' }).trim();
10→const write = (root, path, body) => { const file = join(root, path); execFileSync('mkdir', ['-p', join(file, '..')]); writeFileSync(file, body); };
11→const commit = (root, message) => { git(['add', '-A'], root); git(['commit', '-q', '-m', message], root); return git(['rev-parse', 'HEAD'], root); };
12→const until = async (fn, timeout = 5000) => { const end = Date.now() + timeout; while (Date.now() < end) { const value = await fn(); if (value) return value; await new Promise((r) => setTimeout(r, 10)); } throw new Error('timeout'); };
13→
14→function repo() {
15→  const root = mkdtempSync(join(tmpdir(), 'baton-sm-repo-'));
16→  git(['init', '-q', '-b', 'main'], root); git(['config', 'user.email', 'test@example.com'], root); git(['config', 'user.name', 'Test'], root);
17→  write(root, 'src/value.js', 'export const values = { alpha: 1 };\n'); commit(root, 'base'); return root;
18→}
19→
20→function brief() {
21→  return createBrief({ goal: 'change value', constraints: [], pathScope: ['src/value.js'], definitionOfDone: 'value module remains valid', verification: { command: 'node src/value.js', expectExit: 0 }, budget: { tokens: 1000, usd: 1, wallMin: 1 } });
22→}
23→
24→async function accepted(root, taskId, workerSource, structuredMerge, taskBrief = brief()) {
25→  const adapter = new MockAdapter({ scenario: { outcome: 'completed', edits: [{ path: 'src/value.js', content: workerSource }] } });
26→  const logDir = mkdtempSync(join(tmpdir(), 'baton-sm-log-'));
27→  const driver = createDriver({ repoRoot: root, logDir, adapters: { mock: adapter }, structuredMerge, watchdog: { stallMs: 0 } });
28→  const handle = await driver.coordinator.spawn('mock', taskBrief, { taskId });
29→  await until(async () => (await driver.coordinator.result(handle.id)).ready);
30→  assert.equal((await driver.coordinator.result(handle.id)).status, 'completed');
31→  return { ...driver, handle, logDir };
32→}
33→
34→test('SM1/SM2: missing resolver refuses a conflict without mutating main', async () => {
35→  const root = repo(); const { coordinator, handle } = await accepted(root, 'sm-missing', 'export const values = { alpha: 2 };\n', null);
36→  write(root, 'src/value.js', 'export const values = { alpha: 3 };\n'); commit(root, 'main diverges');
37→  const before = git(['rev-parse', 'HEAD'], root); const status = git(['status', '--porcelain'], root);
38→  await assert.rejects(coordinator.integrate(handle.id, { strategy: 'structured' }), (error) => error.code === 'structured_tool_unavailable');
39→  assert.equal(git(['rev-parse', 'HEAD'], root), before); assert.equal(git(['status', '--porcelain'], root), status);
40→  assert.equal((await coordinator.result(handle.id)).retainedResultRef?.startsWith('refs/baton/results/'), true);
41→});
