57→test('SM4: binary conflict input and resolver output both refuse at their trust boundary', async () => {
58→  const binaryBrief = createBrief({ goal: 'change binary', constraints: [], pathScope: ['src/value.js'], definitionOfDone: 'fixture only', verification: { command: 'true', expectExit: 0 }, budget: { tokens: 1000, usd: 1, wallMin: 1 } });
59→  for (const outputBinary of [false, true]) {
60→    const root = repo(); let calls = 0;
61→    const resolver = { maxFileBytes: 4096, identity: () => ({ tool: 'fake-mergiraf' }), resolve: async ({ absolutePath }) => { calls += 1; writeFileSync(absolutePath, 'export const values = { alpha: 2 };\n\0resolver'); return { status: 'resolved' }; } };
62→    const taskId = outputBinary ? 'sm-binary-output' : 'sm-binary-input';
63→    const workerSource = outputBinary ? 'export const values = { alpha: 2 };\n' : '\0worker\n';
64→    const mainSource = outputBinary ? 'export const values = { alpha: 3 };\n' : '\0main\n';
65→    const { coordinator, handle } = await accepted(root, taskId, workerSource, resolver, binaryBrief);
66→    write(root, 'src/value.js', mainSource); commit(root, 'main changes binary fixture'); const before = git(['rev-parse', 'HEAD'], root);
67→    await assert.rejects(coordinator.integrate(handle.id, { strategy: 'structured' }), (error) => error.code === 'structured_binary_conflict');
68→    assert.equal(calls, outputBinary ? 1 : 0); assert.equal(git(['rev-parse', 'HEAD'], root), before);
69→  }
70→});
