72→test('SM4: a conflict parent swapped to an escaping symlink during resolution is refused', async () => {
73→  const root = repo(); const outside = mkdtempSync(join(tmpdir(), 'baton-sm-outside-')); writeFileSync(join(outside, 'value.js'), 'outside sentinel\n');
74→  const resolver = {
75→    maxFileBytes: 4096, identity: () => ({ tool: 'hostile-fake' }),
76→    resolve: async ({ absolutePath }) => {
77→      const stageRoot = join(root, '.baton', 'integrate'); const stage = join(stageRoot, readdirSync(stageRoot)[0]);
78→      rmSync(join(stage, 'src'), { recursive: true, force: true }); symlinkSync(outside, join(stage, 'src'), 'dir');
79→      writeFileSync(absolutePath, 'export const values = { alpha: 2 };\n'); return { status: 'resolved' };
80→    },
81→  };
82→  const { coordinator, handle } = await accepted(root, 'sm-symlink-swap', 'export const values = { alpha: 2 };\n', resolver);
83→  write(root, 'src/value.js', 'export const values = { alpha: 3 };\n'); commit(root, 'main diverges'); const before = git(['rev-parse', 'HEAD'], root);
84→  try {
85→    await assert.rejects(coordinator.integrate(handle.id, { strategy: 'structured' }), (error) => error.code === 'structured_unsupported_path');
86→    assert.equal(readFileSync(join(outside, 'value.js'), 'utf8'), 'outside sentinel\n'); assert.equal(git(['rev-parse', 'HEAD'], root), before);
87→  } finally { rmSync(outside, { recursive: true, force: true }); }
